var i={en:`A dashboard takes 18 s due to joins on transactional tables with two million activities. Reports may lag by five minutes.`,ua:`Панель відкривається 18 с через JOIN транзакційних таблиць із двома мільйонами дій. Звіти можуть відставати на п’ять хвилин.`};var n={en:[`Identify expensive joins and candidate indexes.`,`Draw a read-optimized projection with incremental updates.`,`Specify reconciliation, freshness and before/after benchmarks.`],ua:[`Визнач дорогі JOIN та потенційні індекси.`,`Намалюй проєкцію читання з інкрементальним оновленням.`,`Опиши звірення, актуальність і бенчмарки до/після.`]};var s=[{en:`Reports avoid unrestricted live-table scans.`,ua:`Звіти не сканують без обмежень робочі таблиці.`},{en:`Source modules retain write ownership.`,ua:`Власники модулів зберігають право запису.`}];var t={scenario:i,tasks:n,checks:s};export{s as checks,t as default,i as scenario,n as tasks};